import{_ as o,o as d,c,a3 as t}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"Android App","description":"","frontmatter":{},"headers":[],"relativePath":"zh/android.md","filePath":"zh/android.md"}'),a={name:"zh/android.md"};function n(s,e,i,r,p,l){return d(),c("div",null,[...e[0]||(e[0]=[t(`<h1 id="android-app" tabindex="-1">Android App <a class="header-anchor" href="#android-app" aria-label="Permalink to &quot;Android App&quot;">​</a></h1><p><code>android/</code> 是手机上的 nanoMuse：<a href="https://github.com/OpenMinis/OpenMinis" target="_blank" rel="noreferrer">OpenMinis</a> 1.13（GPL-3.0）：一个原生 App，智能体<strong>在手机上</strong>运行，Linux shell、浏览器、MCP 服务器、 技能和定时任务都装在 APK 里，再加上 nanoMuse 自己的身份、设计和功能。属于 nanoMuse 的一切 都在 <code>io.github.nanomuse.*</code> 下；OpenMinis 文件里的改动用 <code>// nanoMuse:</code> 标出。应用 id 是 <code>io.github.nanomuse.app</code>，系统认得这个 App 的 URL scheme 是 <code>nanomuse://</code>，这样同一部手机上也装了 OpenMinis 时，不会有两个 App 抢同一个 scheme；App 内部的链接仍是 <code>minis://…</code>（上游的词汇，沙箱、 系统提示词和模型都用它），从系统进来的 <code>nanomuse://</code> 链接按它的 <code>minis://</code> 形式读，App 自己打开 自己的链接时一律按名字指向 <code>MainActivity</code>，不交给系统去解析 （<code>io.github.nanomuse.deeplink.OwnScheme</code>）。沙箱的 offload 套接字（proot 和 App 之间通信的 抽象套接字）也是 App 自己的：叫 <code>io.github.nanomuse.app.native-offload</code>，不用上游的 <code>native-offload</code>，因为抽象套接字在整台设备上只有一个命名空间，两个 App 用同一个名字，后启动的那个 会在启动时直接死掉；如果连这个名字都还被我们自己上一个进程占着，服务端就改绑一个带进程号的名字， 并把它告诉 proot（<code>io.github.nanomuse.sandbox.OffloadSocketName</code>）。这个选择的来龙去脉 在 <a href="./roadmap">roadmap.md</a>；它之前的方案（包着一个 Python 服务器的 WebView，两个 APK 变体） 作为设计记录保留在 <a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/archive/android-python-line.md" target="_blank" rel="noreferrer">archive/android-python-line.md</a>，不是你今天 下载到的东西。</p><p>一个 APK，一种架构：<code>nanoMuse-&lt;version&gt;-arm64.apk</code>（arm64-v8a，Android 8.0 / API 26 及以上， <code>targetSdk</code> 35）。每个版本都用同一把签名密钥，所以新 APK 直接覆盖旧的，数据保留。没有上架 Play 商店：「设置 → 版本」把已安装的构建和最新版本并排显示（先查 <code>nanomuse.cn/dl/index.json</code>， 再查这个仓库的 GitHub Releases：「最新 0.1.x，你用的就是它」/「0.1.x 已发布，点此更新」）， 并提供下载。</p><h2 id="install" tabindex="-1">安装 <a class="header-anchor" href="#install" aria-label="Permalink to &quot;安装 {#install}&quot;">​</a></h2><ol><li>从<a href="https://github.com/nano-muse/nanoMuse/releases/latest" target="_blank" rel="noreferrer">最新版本</a>下载 <code>nanoMuse-&lt;version&gt;-arm64.apk</code>。想核对的话，运行 <code>sha256sum -c nanoMuse-&lt;version&gt;-arm64.apk.sha256</code>。</li><li>打开它。Android 会问一次，是否允许从你的浏览器或文件管理器安装。</li><li><strong>登录。</strong> 第一屏就是账号：手机号或邮箱，一个验证码，设过密码之后也可以用密码。账号让 你的设备能连成一体（<a href="./hub">hub.md</a>），也带来一个起步用的模型（<a href="./cloud">cloud.md</a>：每个 账号一份免费额度（写这页时是 ¥10），每邀请一位朋友，等对方发出第一次请求后，你和对方都再得一些；App 会显示中继 当前的数字；之后可以<a href="./own-key">换自己的 key</a>）。然后选哪个模型来回答：账号自带的，或者 你自己的 key（任何 OpenAI 兼容端点，或 App 内置的那几种 OAuth 登录）。设的是四个模型， 不是一个，都在同一页「<strong>设置 → 模型</strong>」里（设置顶部那张卡片打开它）：<strong>对话</strong>，和你说话 的模型；<strong>操作屏幕</strong>，看屏幕的那个；<strong>生成图片</strong>和<strong>生成视频</strong>。项目托管账号给前两项都推荐 同一个多模态 <code>Qwen/Qwen3.6-27B-FP8</code>，不提供生图或生视频。每一行显示「服务商 · 模型」， 打开一个选择页：登录后只在中继实际菜单覆盖的行里先列 nanoMuse Cloud，然后是你自己每个 服务商一组，只列能做这件事的模型。每组先只显示 8 个模型，点 「还有 N 个」才全部展开（目录里这一行的默认模型排最前，然后是正在用的那个，其余按服务商 列出的顺序）；所有组加起来超过 8 个时，分组上方多一个「搜索模型」输入框，按模型 id 或名称 实时过滤每一组，都不匹配时显示「没有匹配的模型」；搜索词和已展开的分组在旋转屏幕、 去「添加服务商」再回来之后都还在。在这里或在对话的 <code>•••</code> 菜单里 选的对话模型，就是新对话的默认，主要聊天也跟着换（「对主要聊天和新对话生效；旁聊保留自己的模型。」）；已经打开的旁聊保留它的模型。另外三个 选择页第一项是「自动」（操作屏幕例如「当前为 nanoMuse Cloud · Qwen/Qwen3.6-27B-FP8」），选它会忘掉在这里做过的 选择，让这一行重新按下面的顺序走。登录后这一页最上面有一个开关「使用 nanoMuse Cloud 模型」：关掉后，账号从所有选择页和自动顺序里退出，附带调用（标题、记忆、操作屏幕）都不再 走它，只有被拒绝那一轮上的「这次改用 nanoMuse Cloud」按钮例外；登录本身保留，同步和你的 设备照常。如果关掉那一刻对话模型还是账号的，「对话」那一行会换到你自己的第一个对话模型 （目录里该服务商的默认），每个客户端都这么做，页面上写着「对主要聊天和新对话生效」。对话 模型还是账号的、而你又没有自己的对话模型时，关闭会被拒绝并给出一句话：开关保持打开，下面 出现「先添加一个自己的服务商；关掉 nanoMuse Cloud 后没有别的模型能回答。」，因为没有别的 东西能回答。Cloud 这个服务商自己的页面（「设置 → 管理服务商」）遵守同一条规则；在那里关掉 一个正在回答对话的自己的服务商，对话会交给下一个来源，一个都不剩时发送会提示「现在没有 能回答的模型。请在『设置 › 模型』里选一个。」。有自己 key 的手机不登录也能用：欢迎页提供 「改用自己的 API key」。 完全不要账号、一切自己跑，是运行时的 <code>cloud.required = false</code>。</li><li>可选：让智能体能使用你手机上其他 App 的那两个权限（可跳过、可撤销）。「设置 → Hands」 仍保留屏幕模型那一行，点开是同一个选择页；「模型」页底部的「更多图片和视频选项」就是原来的 「图像与视频模型」页（手动输入模型名、缺了哪个模型会停下什么、重新检查一把 key 能用哪些 视频模型），也在 <code>minis://settings/media</code>。</li></ol><p><strong>用它来做什么。</strong> 保存一个你自己的服务商之后（新建的，或给原本没有 key 的补上 key），会有一张 卡片问这把 key 负责哪些事：目录里该厂商每有一项能力就有一个开关（对话、操作屏幕、生成图片、 生成视频），默认全开。「就这样」把勾选的几行切到这个服务商，模型用目录里该项的默认 （<code>providers.json</code> 的 <code>defaults.chat</code> 等），默认不在它的列表里时用列表里第一个能做这件事的； 「暂不」什么都不改，没勾的开关也一样，其他模型选择保持原样。以后在「模型」页改。</p><p><strong>你没选的时候。</strong> 对话：登录了就是中继推荐的模型，否则是你自己的第一个服务商。屏幕、图片、 视频跟着对话的服务商走，只要它是你自己的、且有这项能力（用目录里的默认）；否则登录了就用中继 实际菜单明确为这项工作提供的模型；再否则是你自己第一个能做这件事的服务商。项目托管 Cloud 只有对话和操作屏幕，不提供媒体生成。选过的永远优先，nanoMuse Cloud 不会插到你选 的服务商前面。你自己的模型失败时不会自动兜底：错误卡片多一个「这次改用 nanoMuse Cloud」 （仅登录后显示），只把这次对话或操作屏幕请求放到中继的对话模型上跑，不改任何一行。图片或 视频失败时没有 Cloud 重试，修好或更换你自己的媒体服务商后再试。</p><p><strong>自己的中继。</strong> 登录屏默认连 nanoMuse Cloud，除非你另有指定：登录表单下方的「使用其他服务器」 接受你自己运行的中继地址（<a href="./cloud">cloud.md</a>，<code>cloud/docker-compose.yml</code>），「检查」会请求它的 <code>/healthz</code> 并显示它回答的版本，「使用这个服务器」把地址记住，下次启动仍然有效。自己网络之外的 地址必须是 <code>https://</code>；自己网络内的地址可以用明文 <code>http://</code>，判断规则与模型服务器地址相同 （见下文：按解析后的地址判断私有网段，<code>localhost</code>、不带点的名字，以及 <code>.local</code>、<code>.lan</code>、<code>.home</code>、 <code>.internal</code>、<code>.home.arpa</code>、<code>.localdomain</code>、<code>.ts.net</code> 后缀）。「设置 → 账号」显示「服务器：<code>&lt;host&gt;</code>」和「更改」，更改会先把 手机退出登录：它持有的 key 属于签发它的那台服务器。App 对账号做的一切（登录、hub、同步、 用量、模型菜单）都发往这个地址。</p><h2 id="what-the-phone-does" tabindex="-1">手机能做什么 <a class="header-anchor" href="#what-the-phone-does" aria-label="Permalink to &quot;手机能做什么 {#what-the-phone-does}&quot;">​</a></h2><p>Shell 的进度更新会保留较短覆盖后未被改写的文字。终端的颜色和标题控制码会先移除，避免覆盖后在输出中留下转义序列的残片。</p><p>每次调用带给模型的东西，手机自己也设了一个预算（1.0.8，<code>io.github.nanomuse.chat</code>）。托管模型最近一周的数据里，首字时间随提示大小增长（12k token 以下中位数 4.7 秒，24k 到 40k 之间 25 秒，40k 以上 54 秒），所以 <code>ContextBudget</code> 把压缩线拉到 32k token，64k 以上的窗口一律如此（托管模型按 128k 窗口处理时，原来是 108k），旧的大段工具结果从 28k 起写到磁盘；压缩本身，以及它完整保留的最近几轮，都还是上游的。<code>PromptDiet</code> 把基础提示里最胖的两块改写得更紧凑，不删任何能力：<code>browser_use</code> 的 schema（每个动作和参数都在，cookie、视口、无限滚动那几段写短了）和 Android 工具一节里 <code>minis-*</code> 的几段（其余的在各个 CLI 的 <code>--help</code> 里）。合起来大约 5k 字符，约为过去每次调用在一条消息之前就带上的内容的八分之一。</p><p>一轮还没等到第一个字的时候，输入中的点点下面有一行小字（<code>NmWaitLine</code>）：前十秒什么都不显示，然后是「模型接口比较忙，已等待 15 秒」和「取消」；nanoMuse Cloud 说请求正在等它的模型名额时（中继 0.31 每 5 秒发一段没有 <code>choices</code>、带 <code>nanomuse: {phase, ahead}</code> 字段的 chunk，<a href="./cloud#protocol">cloud.md</a>），一知道就改为「前面还有 3 个」或「下一个就到你」（<code>NmStreamStatus</code>，<code>OpenAIProvider</code> 里标记的一行）。用到工具的一轮里，每一步各自计时。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>智能体，在手机上</strong></td><td>一个沙箱里的 Alpine Linux、一个真正的 shell、文件、浏览器、MCP 服务器、Agent Skills 格式的技能、记忆、定时任务；删除、发送、付款之前先审批。模型是账号的或你自己的；用自己的 key 时，对话本身从手机直接发给那家服务商，不经过项目的中继；1.0.7 起，答完的那一轮会事后补进你账号的记录（模型的 id 和这一轮，从不包括 key），让你的其他设备也有它（<a href="./cloud#the-record">cloud.md</a>）。</td></tr><tr><td><strong>手（Hands）</strong>（<code>hands/</code>）</td><td>打开「Hands」并启用无障碍服务之后，智能体会看手机的屏幕，在各个 App 里点、输入、滑动：这是 API、抓取和浏览器之后的最后一级。盖在 App 上的舞台显示它即将点哪里，一个胶囊显示当前步骤和<strong>停止</strong>；屏幕边缘有一圈呼吸的光（干活时蓝色，等你时琥珀色；亮 2.4 s、暗 2.4 s，第 9 轮起每个客户端上每一处「在干活」的灯都是这个节奏：没有东西绕着边缘跑，也没有东西从屏幕上扫下来，胶囊的环和竖条按同样的节奏呼吸；系统设了「减弱动态效果」时全部静止）；当一次点击会发送、发布或删除时，胶囊自己就会问（<strong>允许</strong> / <strong>拒绝</strong>，和聊天卡片、通知显示的是同一个请求），所以你不用被拉回 nanoMuse（付款在聊天卡片里用锁屏确认；对这一种，胶囊提供「打开」）；胶囊只回答它自己的请求，不会替另一段对话的命令行或浏览器卡片作答，卡片等待期间按<strong>停止</strong>会直接拒绝它并立刻结束这次运行。密码和验证码永远由你自己输。屏幕没有变化而同一个动作做到第三次，历史里会记一笔，好让模型换个法子；做到第六次，这一轮就以「做不到」结束并写明是哪个动作（<code>HandsLoopWatch</code>，运行时也有同样的底线），而不是每一步都调用一次模型，直到三十分钟上限。每一步的截图写在会话的 <code>attachments/hands/&lt;run&gt;/</code> 下、与这次运行的轨迹放在一起；最新的十次运行保留全部截图，更早的运行只保留轨迹和最后一张屏幕（聊天里显示的那张），超过 200 次之后最早的一次整个删除（<code>HandsTraces</code>）。<a href="./gui">gui.md</a> 是设计记录；App 自己的手在 <code>io.github.nanomuse.hands</code>。</td></tr><tr><td><strong>Reach</strong>（<code>reach/</code>）</td><td>从手机使用你的电脑：「手机上说一句，电脑上执行」，一条 shell 命令、一个文件、电脑的屏幕，或者把整个任务交给那边运行的 nanoMuse。入口是 hub（下一行）：在电脑上装 nanoMuse 桌面版，用同一个账号登录，几秒钟内它就出现在「账号 → 设备」下，不限网络；从 0.1.24 起这是唯一的方式（局域网的 host 脚本已经去掉）。「设置 → 电脑」列出账号下的电脑，并说明手机用的是哪个账号，因为电脑不见了，几乎总是因为它登的是另一个账号。审批在手机上决定之后，才会发出任何东西。<a href="./every-device">every-device.md</a>。</td></tr><tr><td><strong>hub</strong>（<code>hub/</code>）</td><td>账号下每台登录的设备都在中继的 hub 上相遇：手机看得到你的电脑，能拜托它们做事，把它们的审批当作卡片收到，也能被它们拜托。一个前台服务让它在后台也保持可达（Android 13 及以上为此会请求通知权限）。<a href="./hub">hub.md</a>。</td></tr><tr><td><strong>编程助手</strong>（<code>ui/coding/</code>）</td><td>你电脑上的 Cursor、Codex 和 Claude Code 会话，在手机上看、在手机上指挥。<a href="./coding-agents">coding-agents.md</a>。</td></tr><tr><td><strong>账号</strong>（<code>ui/cloud/</code>）</td><td>谁登录了、密码、每台持有 key 的设备、按类别和按模型的用量、退出的方式。免费额度用完或超过 80 % 时，账号页和被拒绝的那一轮都会显示接下来的路：自己的 key，也就是目录里的服务商，所在地区的排前面（中国大陆的人看到阿里云百炼：判断依据是界面语言为简体中文、用手机号登录，或者中继这么说；其他地方是 OpenRouter 和 OpenAI），每一家都写明它覆盖什么；你已经在付费的套餐（ChatGPT、Claude、Kimi、OpenRouter 用登录代替 key）；还有邀请。见下面的<a href="#your-own-key">自己的 key</a>。手机只显示、只同步当前登录账号的对话：从 0.1.40 起每个聊天都有一个归属者，同步与否都是；退出登录时会问「在这台设备上保留这个账号的聊天」（默认关：这个账号的聊天、记忆、动态、目标、例程和形象都离开手机；开：先收起来，等它回来）；删除账号会把这些全部删除；中继拒绝的 key（<code>401 bad_key</code>）会像「保留」那样把账号的数据收起来，登录页会一直说明，直到下次登录；只有 <code>401 account_deleted</code> 会删除；退出登录状态下，只显示退出后产生的聊天（<a href="./sync">sync.md</a>）。</td></tr><tr><td><strong>交到你手里的浏览器</strong>（<code>browser/</code>）</td><td>需要你亲自处理的页面（登录、验证码、付款、人机验证）会直接交到你手里，而不是用文字描述：<code>browser_use</code> 的 <code>hand_over</code> 动作把智能体自己的标签页（同一个 WebView、同一个会话）在浏览器面板里打开，智能体松手；输入框上方的<strong>轮到你了</strong>卡片说明页面要你做什么，带「打开页面」和「完成，继续」，面板上是同一句话和同一个按钮，工具调用会等到「完成」（最多十五分钟），然后智能体从页面当前的样子接着往下做。<code>io.github.nanomuse.browser.BrowserHandOver</code>。</td></tr><tr><td><strong>连接器</strong>（<code>connectors/</code>、<code>ui/connectors/</code>）</td><td>智能体可以被放进去的那些服务：桌面版那份 75 个远程 MCP 服务器的目录（Notion、Linear、GitHub、GitLab、Slack、Stripe、Miro……），以 <code>assets/nanomuse/connectors.json</code> 随 App 发布。设置里管这一切的只有一行：「连接器」；上游的 MCP 编辑器（按地址、按命令、导入 JSON）是页面末尾的「你自己的服务器」。开放的服务点一下就加上；要 key 的服务填 key；OAuth 服务走 MCP 授权流程（发现、动态客户端注册、在 Custom Tab 里做 PKCE），令牌进入该条目的 <code>Authorization</code> 头，供沙箱内的 MCP 客户端使用，App 启动时刷新；授权服务器不接受注册客户端的服务（<code>clientIdRequired</code>：GitHub、Slack、Discord、HubSpot、Render、Bitrise、PagerDuty、Box）会要你在厂商的开发者页面用 App 的回调地址创建一对 OAuth client id 和 secret，面板会显示并复制这个回调地址。连接好的服务就是同一个 id 下的一个 MCP 服务器条目；「你自己的服务器」也能管它。连接了什么，会通过中继的 profile 分享给账号的其他设备，只有条目（id、名称、地址、认证方式、哪台设备、何时），从不包含令牌，所以页面还会列出「在你的其他设备上」：在桌面上连接的服务显示为「已在 &lt;device&gt; 上连接，在这里登录即可在这台手机上使用」，点一下进入同一个面板。</td></tr><tr><td><strong>聊天，不花哨</strong></td><td>智能体工作时，形象下面那一行写的是正在进行的步骤（「nanoMuse 正在用 Shell」「正在写回复」「在做了：订餐桌」），从不写心情。工具小标签、「电脑」面板和浮动的步骤条从 0.1.37 起<strong>默认打开</strong>；「设置 → 外观 → 显示智能体的步骤」可以关掉它们。打开时，完成的步骤显示为「nanoMuse 用过 Shell · 完成」，它的面板点 ×、滑动或返回键都能关。</td></tr></tbody></table><p>聊天和胶囊栏、菜单、抽屉在同一块底色上：深色主题是纯黑，浅色主题是纯白。你的消息是白色胶囊、黑色文字（浅色主题下反过来，黑色胶囊、白色文字）， 智能体的回复放在比底色略浅一级的胶囊里（<code>#1C1C1E</code> / <code>#F2F2F7</code>），发送按钮和「回到最新」圆盘是白底黑箭头（浅色主题下反过来）； 除了链接，对话里没有蓝色。顶栏不是一条横条，而是一层渐隐：对话从它下面滚过去，渐渐融进底色；往回翻旧消息时，顶边还会多出一层渐隐。 调色板在上游的 <code>com/openminis/app/ui/theme/ChatColors.kt</code>，由 <code>scripts/rebrand.py</code> 写入。</p><p>消息输入框始终位于浮动导航胶囊上方，胶囊栏和输入框一样宽（同样的 16 dp 边距；最宽 420 dp，更宽的屏幕上居中），两枚胶囊的边缘对齐。智能体使用工具时，步骤条在输入框上方； 最新消息和工具小标签都可以完整滚动到它们上方。对话仍会滚过导航胶囊背后， 保留磨砂模糊效果。输入框展开、工具预览或审批卡片出现时，间距跟着底部区域的实际高度调整。 审批卡片本身最多占屏幕的三分之二：超过六行的命令折叠在「全部显示」后面，说明和预览在中间滚动，「允许」和「拒绝」始终留在底部可见。 查看较早的消息时，稍淡的渐隐效果沿着输入框的圆角轮廓展开。 只有当前浏览器操作的步骤条、浏览器面板或「轮到你了」操作卡片显示时，这层渐隐才会隐藏；历史工具小标签和其他工具不会关闭它。 深色模式下，主要聊天和旁聊的导航胶囊周围为纯黑色，输入框下方的间隙也会被盖住。 胶囊的玻璃区域仍透出滚动内容，保留实时磨砂模糊效果。其他页面的导航外观保持原样。 键盘弹出时，输入框贴在键盘上，胶囊栏在键盘后面。 动态、点子、目标和资源库四个页面的列表也在胶囊栏上方结束，最后一行不会被它挡住。</p><p>同一个账号的网页控制台在中继上（<code>/app</code>），桌面版见 <a href="./desktop">desktop.md</a>；手机、桌面和网页共用 <a href="./brand">brand.md</a> 里描述的设计语言。</p><p>在「设置 → 外观」中，「聊天输入」「消息文本」和「应用基础」的字号标签会跟随应用语言。</p><h2 id="your-own-key" tabindex="-1">自己的 key <a class="header-anchor" href="#your-own-key" aria-label="Permalink to &quot;自己的 key {#your-own-key}&quot;">​</a></h2><p>App 认识的厂商在一个文件里，<code>assets/nanomuse/providers.json</code>，运行时的 <code>nanomuse/llm/providers.json</code> 的一份拷贝，由 <code>node scripts/providers-json.mjs</code> 写出，每个客户端读的 都是这同一份目录（<a href="./own-key">own-key.md</a>）。每个条目写明端点在哪、在哪里创建 key、有哪些登录方式、 在哪里接受注册（<code>cn</code>、<code>global</code>），以及它的模型能做什么：<code>chat</code>、<code>vision</code>（手看屏幕）、<code>image</code>（图片）、 <code>video</code>（短视频）。</p><p><strong>卡片。</strong> 额度用完或快用完时，「使用自己的模型 key」列出目录，所在地区的厂商在前：大陆是 阿里云百炼（一把 key 覆盖全部四项；它只接受中国大陆的账号注册），其他地方是 OpenRouter 和 OpenAI；然后是其余的，每次三家，收在「更多服务商」后面。每一行都写明这家覆盖什么 （「聊天 · 屏幕 · 图片 · 短视频」）；「添加」打开服务商表单，预填好它的名字、端点和 <code>/v1</code> 设置 （<code>minis://settings/providers/add?preset=&lt;id&gt;</code>），「获取 key」打开厂商的 key 页面。不推荐任何一家。 「你已经在付费的套餐」列出用套餐登录、不用 key 的厂商：ChatGPT（OpenAI 的 Codex OAuth）、 Claude、Kimi（设备码）和 OpenRouter；「登录」打开同一个表单并停在登录按钮上（<code>?preset=&lt;id&gt;:oauth</code>）， 走的是 OpenMinis 自己的 <code>OpenAIOAuthManager</code>、<code>ClaudeOAuthManager</code>、<code>KimiOAuthManager</code> 或 <code>OpenRouterOAuthManager</code>。ChatGPT 那一行附一句话：OpenAI 的条款只允许 ChatGPT 套餐在 OpenAI 自己的 Codex 里使用，别的 App 曾被切断过这种访问（OpenCode，2026 年 1 月），如果停了，API key 照样能用。Anthropic 和 Gemini 打开的是 OpenMinis 为它们准备的服务商类型；其他都走 OpenAI 兼容表单。Claude 登录需要 Anthropic 要求放在每个请求开头的一段标识；它在构建时从 <code>app/provider-customization.properties</code> 读入，这个文件不在仓库里，所以发布的 APK 没有它。没有这段 标识的构建不会列出 Claude 登录（这张卡片上没有，「添加服务商」里没有，<code>?preset=anthropic:oauth</code> 打开的是 API key 表单）；早先版本保存下来的 Claude 登录，每次发送都会得到一句「这个版本不能用 Claude 账号登录。请改用 API key 添加 Anthropic。」，而不是让 App 退出（<code>io.github.nanomuse.cloud.ClaudeSignIn</code>）。</p><p><strong>列表从哪来。</strong> 中继的 <code>/v1/me</code> 带着 <code>spend.guidance</code>（中继 0.21，<a href="./cloud">cloud.md</a>）：这个人所在 地区的服务商，按中继的顺序，每家覆盖什么、可以登录的套餐以及它们面向哪些客户端、本地服务器、 文档链接，还有关于 ChatGPT 登录的那句实话。<code>cloud/Guidance.kt</code> 解析它，<code>Ways.resolve</code> 优先用它， 卡片和「设置 → nanoMuse Cloud」只在中继没发（旧中继）时才读内置目录，所以中继上新加的厂商 不用等 App 更新就能出现，中继不再列出的服务商当天就消失。<code>429 allowance_exhausted</code> 在数字旁边 带着同一块内容。</p><p><strong>各家覆盖什么。</strong> 能力决定 App 提供什么（<code>cloud/Capabilities.kt</code>）：图片（「设置 → 模型 → 生成图片」、 形象工作室、<code>nanomuse-media image</code>）只在厂商有 <code>image</code> 的服务商里挑；短视频只在有 <code>video</code> 且 App 能驱动的里面挑（百炼的视频 API）；屏幕模型和它的选择页只列出有 <code>vision</code> 的厂商的模型。通过 Codex 登录的 ChatGPT 套餐只有聊天和视觉（Codex 后端没有图片或视频端点），所以从不会被拿来 画图。目录不认识的厂商（一个网关、你自己的中继、nanoMuse Cloud）按它模型自己的说法算，和以前 一样。没有任何已配置的服务商具备某项能力时，页面用一句话说明（「画图需要有图像模型的 服务商：百炼、OpenAI、Gemini 或 OpenRouter。」），而不是报错。</p><p><strong>一把 key 有哪些视频模型。</strong> 百炼的 <code>/models</code> 列表里没有视频模型，所以 App 拿一个不计费的空任务 逐个去问这个版本认识的那几个模型（<code>VideoGen.KNOWN_DASHSCOPE_MODELS</code>，万相 2.2 Flash 排第一）， 答案记一天。「视频」选择页列出这份答案，再加上你自己在该服务商下列出的每一个视频模型——名字 带 <code>t2v</code>、<code>i2v</code> 等字样的条目，或者详情里输出模态标了 <code>video</code> 的条目（名字叫什么都行）——原样 列出，不管探测有没有确认过。要问的模型一变（你加了条目，或新版本认识了新模型），记下的答案 立刻重新去问，不用等满一天。「图像与视频模型」页仍保留手动输入模型 ID 的输入框。 （<a href="https://github.com/nano-muse/nanoMuse/issues/508" target="_blank" rel="noreferrer">#508</a>）</p><p>在形象工作室重新生成候选图时，新一组会替换旧一组。旧请求随后返回的图片或失败结果，不会改动新一组的候选格或文件。点击重新生成即可开始新请求，无需等待旧图片保存完毕。</p><p><strong>连不上服务商的时候</strong>（<code>net/ProviderReach.kt</code>、<code>ui/chat/ProviderReachCard.kt</code>）。失败的一轮，如果 错误来自传输层（OkHttp 的「failed to connect to chatgpt.com/…（port 443）」「Unable to resolve host」、 一条 TLS 或超时信息），或者是 OpenAI 的「region not supported」，就显示为一张卡片而不是红色横幅： 发生了什么、什么有用（这台手机上的 VPN、「设置 → 网络」下的代理、另一家用你自己 key 的服务商）、 「重试」，以及收在「详情」后面的原始信息。上游的 <code>mapHttpError</code> 会丢掉 401/403/429 的响应体， <code>ReachSignal</code>（<code>OpenAIProvider</code> 里一处 <code>// nanoMuse:</code> 改动）把它们留几秒钟，以规范的 <code>nm_reach:</code> 行 写进消息，所以过期的 ChatGPT 登录显示「重新登录」，用完的套餐窗口显示「ChatGPT 套餐暂时没有 剩余了」，附 OpenAI 自己的那句话和重置时间；key 服务商上普通的「Invalid API key」则保持上游的 样子。中继的 <code>daily_cap</code> 429 现在和 <code>allowance_exhausted</code> 一样读取，卡片会说今天的份额用完了， 隔天回来。额度卡片还列出你自己的模型（你自己电脑上的 Ollama、LM Studio、vLLM），以及对登录 账号而言，你的电脑：聊天里打「@」加它的名字，这一轮就在那边跑。</p><p><strong>中继拒绝一轮的时候</strong>（<code>cloud/RelayRefusal.kt</code>、<code>ui/chat/RelayRefusalCard.kt</code>）。nanoMuse Cloud 发来的 每一种拒绝都是手机语言的一句大白话，加上一个合适的按钮，从不显示状态码、中继的 JSON 或上游的 「Rate limited」。回复在响应体还完整时读取（<code>AllowanceSignal.noteHttpError</code>，经由 <code>OpenAIProvider</code> 里 同一处 <code>// nanoMuse:</code> 改动），以规范的 <code>nm_relay:</code> 行存进消息，由卡片绘制：<code>413 too_large</code>（也包括 中继主机上的代理返回的普通 413）→「这条消息对模型来说太大了。缩短一点、去掉一些附件，或者开 一个新聊天。」加「新聊天」；<code>400 content_rejected</code>（服务商的内容审核没有放行这些内容；用自己的 key 时服务商自己的 <code>DataInspectionFailed</code> 也算）→「模型服务商的内容审核没有放行这次请求。换个说法 试试；如果反复出现，就新开一个对话，被拦下的可能是对话里更早的内容。」加「新聊天」和「重试」， 压缩的对半重试（<code>ChatViewModel.shouldSplitOnError</code>）不碰它，因为请求再小，同样的内容回来还是被拒； <code>401 bad_key</code> / <code>account_deleted</code> →「登录」；<code>403 not_invited</code> / <code>account_disabled</code> / <code>signup_closed</code> →「打开设置」；<code>429 too_many_in_flight</code> / <code>locked</code> / <code>rate_limited</code> 和 <code>provider_busy</code>（附 <code>retry_after</code> 的等待时间）→「重试」；<code>404 model_not_offered</code> →「打开设置」；<code>503 service_paused</code>、<code>sync_paused</code>、<code>hub_paused</code> 以及任何 5xx 或空响应 →「重试」。<code>429 allowance_exhausted</code> 和 <code>daily_cap</code> 保留额度卡片；带 <code>paused: true</code> （中继 0.22）时，卡片开头说额度「在这个中继上暂停了，不是用完了」，剩下的保持不变。这些句子 来自 <code>NanoMuseCloud.describe</code>，和登录页、账号页用的是同一批，17 种语言都有（<code>nm_cloud_err_*</code>）。 单元测试：<code>RelayRefusalTest</code>、<code>GuidanceTest</code>。</p><p><strong>设置 → 网络</strong>（<code>net/OwnProviderProxy.kt</code>、<code>ui/net/NetworkScreen.kt</code>、<code>minis://settings/network</code>）。 给自己的服务商用的 HTTP 代理：主机、端口、可选的用户名和密码，默认关闭，只存在这台手机上：设置项在 <code>SharedPreferences</code> 里，密码单独放在一个 <code>EncryptedSharedPreferences</code> 文件里（<code>nanomuse_proxy_secrets</code>， 和服务商 key 一样的存法；1.0.3 的手机存在普通文件里的密码会在第一次读取时搬过去）。它在 <code>MinisApp.onCreate</code> 中被装为进程默认的 <code>ProxySelector</code>，所以每个 OkHttp 客户端每次请求都会问它；对目录里的主机、<code>chatgpt.com</code>、<code>auth.openai.com</code> 和服务商实例的自定义 base URL（从不包括中继的，从不包括局域网地址）它回答代理，对其他所有主机回答系统的设置：hub、 中继、沙箱镜像都不受影响。服务商客户端带着 <code>OwnProviderProxy.authenticator</code>，应付要密码的代理。 「测试」按填写的代理抓取 <code>https://chatgpt.com/</code>，报告状态码和毫秒数。单元测试：<code>ProviderReachTest</code>、 <code>OwnProviderProxyTest</code>。</p><p>离开登录页或「网络」页，会取消该页尚未完成的请求，服务器已开始回复但还未传完时也一样。</p><h2 id="voice-input" tabindex="-1">语音输入 <a class="header-anchor" href="#voice-input" aria-label="Permalink to &quot;语音输入 {#voice-input}&quot;">​</a></h2><p>Android 13 及以上的系统连续听写在识别器切换到下一段时会继续传入音频。上一段已关闭管道的写入失败，不会再清除新一段的音频流。</p><p>使用服务商语音模型时，静默录音达到时限，或极短语音等待补充超时后，面板会回到空闲状态。已经开始的转写仍会等待结果，不会被空结果提前结束。</p><p>系统语音输入可以优先使用设备端识别。手机没有可用的设备端识别服务时，会改用默认识别服务；默认服务返回的语言错误会显示在语音面板中。已经启动的设备端识别器缺少语言包时，仍会尝试一次默认服务。</p><p>录音无法启动，或在开始采集前被取消时，语音检测器也会释放已经创建的录音器，避免重试语音输入时留下未释放的录音器。</p><p>一段话在静音后结束时会送去转写并关掉麦克风，而这个关掉过去是在语音检测器自己的回调里、同一个线程上，把它正在运行的原生对象直接释放掉：说满两秒以上再停下来，App 就会原生崩溃（1.0.8 修好了；上游 OpenMinis 1.14 有同一处改动）。现在回调里发起的停止，要等检测器把这一帧处理完交回来才生效。</p><h2 id="privacy-and-permissions" tabindex="-1">隐私与权限 <a class="header-anchor" href="#privacy-and-permissions" aria-label="Permalink to &quot;隐私与权限 {#privacy-and-permissions}&quot;">​</a></h2><p>中继保存账号 id、一个打码的标识、用量计数，以及智能体的名字和外观（让你的设备保持一致）； 你的对话有三份：记录（和中继模型的每一轮完整保存，1.0.7 起用自己 key 的轮次也补进来，你的设备和运行中继的人能读， 在<em>数据控制</em>里一键删除）、对话同步（登录后默认开启，在<em>数据控制</em>里关掉），以及只在「帮助改进」开着时才进入的训练集 （<a href="./privacy">privacy.md</a>、<a href="./cloud#the-record">cloud.md</a>、<a href="./sync">sync.md</a>）；第一次对话的第四句话会这么说。 <em>数据控制</em>会显示记录里有这个账号的多少轮（其中多少轮用自己的 key、多少张图片），以及这个中继保留多久。在手机上，API key 和账号 key 放在 <code>EncryptedSharedPreferences</code> 里，<em>设置 → 网络</em> 的代理密码也是（1.0.4 起；只在这台手机上）；从 0.1.40 起 App 完全不参与设备备份（<code>allowBackup=&quot;false&quot;</code>： 聊天、记忆和 key 从不上传到 Google，重装后从空白开始，账号的聊天通过同步回来；<code>res/xml/</code> 下的 两个规则文件留着，等哪天开关再打开时用）。手需要无障碍服务和悬浮窗权限，两者都可选、都能在 同一屏撤销（首次运行的「手」那一页在 App 标志下面请求这两项，和登录页一样）；会发送东西的步骤（点「发送」，或在聊天软件的消息框里按回车）一次一次地审批， 「本次对话」的答复也只对当初授权的那个 App 或地址有效。账号下的另一台设备想在手机上运行、读取 或写入什么（hub 的 <code>shell</code>、<code>files</code>、<code>open</code>、<code>screen</code>……），要先经拿着手机的人批准：「一次」或 「对这台设备总是允许」，可在「权限」里撤销。另一台设备或智能体说出的路径（hub 的 <code>files</code>、 <code>nanomuse-media</code>、<code>nanomuse-pc put</code>）只在沙箱内解析（<code>io.github.nanomuse.sandbox.SandboxPaths</code>）： <code>..</code> 和指向 rootfs 之外的符号链接都无处可去，App 自己的私有文件始终够不着。App 只对你自己网络内的地址（私有网段 <code>10/8</code>、<code>172.16/12</code>、 <code>192.168/16</code>、Tailscale 分配的 <code>100.64/10</code>、链路本地地址、IPv6 ULA、<code>localhost</code>、不带点的名字， 以及 <code>.local</code>、<code>.lan</code>、<code>.home</code>、<code>.internal</code>、<code>.home.arpa</code>、<code>.localdomain</code>、<code>.ts.net</code> 后缀），也就是一台模型 服务器或你自己的电脑，允许明文 <code>http://</code>，其他地址在服务商 URL 字段里一律拒绝 （<code>io.github.nanomuse.net.LanOnly</code>）。地址先解析再判断，所以 <code>10.foo.example.com</code> 这样的公网名字 不会被当成私有地址。自己的中继能否用 <code>http://</code> 也按同一条规则判断；nanoMuse Cloud 以及到它的 hub 只走 TLS。App 内的 web view 不对其他 App 导出。用服务商语音模型做语音输入时，麦克风只在录音期间打开：停止或取消录音都会立刻关掉录音器，取消的那段音频直接丢弃，不会发给服务商。</p><p><strong>除了这一轮本身，记录还会听到什么</strong>（中继 0.31）。发给 nanoMuse Cloud 的聊天请求，除了设备和对话的 id，还会带上这次调用在对话里的位置： 这一轮是谁发起的（<code>X-NanoMuse-Run</code>：你本人、定时任务、动态的例行程序、目标的检查、另一台设备通过 hub 托付的任务）、 按聊天自己的计数这是第几轮、这次调用是这一轮里的第几次、手在操作屏幕时所属的那次运行及其步数，以及 <code>X-NanoMuse-Platform: android</code>； 用自己 key 跑的轮次上传时带同样的字段（<a href="./cloud#provenance">cloud.md</a>；<code>io.github.nanomuse.cloud.Provenance</code> 从聊天的协程里读出这些， 所以手打的消息、重试、例行程序的提示、hub 任务和手的每一步说的都是同一套）。登录状态下，手机还会把一轮前后发生的事以短记录发上去 （<code>POST /v1/events</code>，<code>io.github.nanomuse.cloud.ClientEvents</code>）：风险闸门对每条 shell 命令、浏览器点击、屏幕步骤的判定和那张卡片是怎么答的， 手的每一步和这次运行是怎么收尾的，一轮是被手动停下还是出错结束，以及最新回复下面的两个拇指和停止之后的那一个问题 （「为什么停下来？」，五个一词的答案加「跳过」；例行程序或另一台设备的那一轮不会问）。只有代码和数字——工具的种类、风险档、谁答的、等了多久—— 从不包含命令、页面、屏幕或对话里的任何一个字（<a href="./cloud#client-events">cloud.md</a>）；<em>数据控制</em>里的删除会把它们和轮次一起删掉。</p><h2 id="building-it-yourself" tabindex="-1">自己构建 <a class="header-anchor" href="#building-it-yourself" aria-label="Permalink to &quot;自己构建 {#building-it-yourself}&quot;">​</a></h2><p>JDK 21（CI 用的也是它）和 Android SDK（Android Studio 会把两个都装上）；<code>scripts/android/env.sh</code> 在一台空机器上 设好环境。工程在 <code>android/src/android</code> 下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/android/build-natives.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 只需一次：proot、Alpine rootfs 和 rclone.aar（NDK r27c，Go 1.25+）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android/src/android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleDebug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # app/build/outputs/apk/debug/app-debug.apk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleRelease</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # signed with android/keystore.properties when present</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:testDebugUnitTest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;io.github.nanomuse.*&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 我们的单元测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:lintDebug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # Android lint；报告在 app/build/reports/lint-results-debug.html</span></span></code></pre></div><p>Lint 用的是比 AGP 8.7.3 自带版本更新的 lint（<code>gradle.properties</code> 里的 <code>android.experimental.lint.version</code>）：Compose 和 lifecycle 库自带的检查，自带的那个加载不了。上游树里有 它自己的 lint 发现；看报告时找 <code>io.github.nanomuse</code> 的部分。</p><p><code>rclone.aar</code> 用 Go 构建，模块走 Go 自己的默认代理（<code>https://proxy.golang.org,direct</code>）；在中国大陆网络下先 <code>export GOPROXY=https://goproxy.cn,direct</code>，<code>env.sh</code> 会沿用你导出的值。</p><p><code>scripts/rebrand.py</code> 带着版本号（<code>VERSION_NAME</code>、<code>VERSION_CODE</code>），把 nanoMuse 的命名套到 OpenMinis 树上；<code>android/BUILDING.md</code> 讲原生部分。没有签名密钥时，release 构建用 debug 密钥签名， 能安装，但不能升级一个正式签名的构建。要签名，先创建一次密钥，放在仓库之外：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -genkeypair</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nanomuse-release/nanomuse.jks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -alias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        -keyalg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RSA</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keysize</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -validity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10950</span></span></code></pre></div><p>然后把它的四个值填进 <code>android/keystore.properties</code>（已 git-ignore：<code>storeFile</code>、 <code>storePassword</code>、<code>keyAlias</code>、<code>keyPassword</code>）。</p><p>仅用于聊天测试的模拟器构建（<code>-Pnm.abi=x86_64</code>）会排除缓存中的 arm64 proot 和 Alpine 根文件系统资源。切回默认的 arm64 构建后会重新包含这些资源，无需删除缓存。</p><h2 id="releases" tabindex="-1">发布 <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;发布 {#releases}&quot;">​</a></h2><p><code>.github/workflows/android.yml</code> 在 <code>android/</code> 下每有改动就构建 debug APK（「debug APK · arm64-v8a」 这项检查）。版本由 <code>scripts/release-apk.sh &lt;version&gt;</code> 从一个标签做出来：它核对版本号与 <code>rebrand.py</code> 和 Gradle 是否一致，用 release 密钥构建 <code>:app:assembleRelease</code>，写出 <code>dist/nanoMuse-&lt;version&gt;-arm64.apk</code> 和它的 <code>.sha256</code>，加 <code>--publish</code> 时打上 <code>v&lt;version&gt;</code> 标签， 并把两者连同 <code>docs/releases/v&lt;version&gt;.md</code> 里的说明一起附到 GitHub release 上。工作区有未提交的改动， 或者提交不在 <code>main</code> 上，发布会被拒绝。debug 签名的 APK 永远不进 release，因为正式签名的版本无法覆盖它。<code>versionName</code> 必须和标签一致，就像 Python 包的 版本号那样。</p><h2 id="where-things-are" tabindex="-1">东西都在哪 <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;东西都在哪 {#where-things-are}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径（<code>android/src/android/app/src/main/java/io/github/nanomuse/</code>）</th><th>作用</th></tr></thead><tbody><tr><td><code>cloud/NanoMuseCloud.kt</code></td><td>账号：用验证码或密码登录、加密存储里的 key、<code>/v1/me</code>、用量、会话、本地化的错误句子；中继的菜单和它的两个默认值（<code>for: chat</code> / <code>for: gui</code>）</td></tr><tr><td><code>cloud/Region.kt</code>、<code>cloud/ProviderCatalogue.kt</code>、<code>cloud/Capabilities.kt</code>、<code>cloud/OwnKeyPresets.kt</code>、<code>cloud/ProfileSync.kt</code></td><td>哪个地区的厂商排前面（大陆 → 百炼，否则 OpenRouter 和 OpenAI）；从 <code>assets/nanomuse/providers.json</code> 读出的自带 key 目录，以及某个已配置的服务商对应哪家厂商；一个服务商覆盖什么和那些一句话的「不可用」提示；预填的服务商表单（<code>?preset=&lt;id&gt;[:oauth]</code>）；拉取和推送的中继 profile（名字、外观、连接器）</td></tr><tr><td><code>sync/</code></td><td>对话同步（契约 C7–C10）：<code>SyncEngine</code>（什么上传、什么下载；每个映射带 <code>owner</code>，只有本账号的）、<code>ConversationSync</code>（何时同步；<code>hidden</code>：另一个账号的聊天，从 <code>ChatRepository.observeSessions()</code> 里排除）、<code>LocalChats</code>、Room 存储 <code>nanomuse_sync.db</code>（含 C12 的 <code>session_owners</code> 表）</td></tr><tr><td><code>account/</code></td><td>契约 C12（0.1.40，<a href="./sync">sync.md</a>）：<code>AccountScope</code>（规则：一个会话是谁的聊天、账号的 key、列表排除什么、被拒绝的 key 保留什么（<code>keepOnRefusedKey</code>：全部保留，除非中继说 <code>account_deleted</code>）；有单元测试）、<code>AccountData</code>（执行规则：每个聊天一行归属记录，<code>leave</code> 把账号的聊天、记忆、动态、目标、例程、形象和偏好收起来或删掉，<code>enter</code> 把一个账号的东西带回来）。「库」标签遵循同一条规则：只列出聊天列表会显示的那些会话的工作区，共用一台手机时另一个账号的文件不会出现（<code>library/LibraryIndex.shows</code>，有单元测试）</td></tr><tr><td><code>hub/</code></td><td><code>Hub</code>（状态、设备身份、设置）、<code>HubClient</code>（带退避的 socket；key 被拒绝时每分钟重试一次并如实显示，连接被替换时等 30 秒，运营者暂停 hub 时等两分钟并如实显示）、<code>HubService</code>（前台服务）、<code>HubActions</code>（其他设备可以让这台手机做什么；\`stop {call</td></tr><tr><td><code>reach/</code></td><td><code>Computers</code>（账号的设备，按 hub 列出的样子，以及对它们的调用；0.1.24 起不再有配对，也没有自己的令牌）、把工作转交给电脑的处理器</td></tr><tr><td><code>models/</code></td><td>「设置 → 模型」背后的逻辑：<code>ModelSlots</code>（四个槽位、各自设成了什么、存在哪里、选择页列出的分组、对话默认的 <code>followPick</code>、「用它来做什么」卡片的 <code>applyProvider</code>），<code>SlotOrder</code>（解析顺序和目录默认，纯 Kotlin，有单元测试），<code>PickerList</code>（选择页每组 8 行的折叠、排序和搜索过滤，纯 Kotlin，有单元测试）</td></tr><tr><td><code>ui/models/</code></td><td>「模型」页、每一行背后的选择页、「用它来做什么」卡片（<code>minis://settings/models</code>）</td></tr><tr><td><code>chat/CloudRetry.kt</code></td><td>「这次改用 nanoMuse Cloud」：卡片何时提供它，以及 <code>ChatViewModel.retryLast</code> 这一轮用的服务商</td></tr><tr><td><code>chat/RoutineWakes.kt</code>、<code>ui/chat/NmRoutineWakeRow.kt</code></td><td>定时任务的一轮是例程的，不是本人的：<code>ScheduledAgentRunner</code> 在提示词发出前先登记一次唤醒，<code>ChatViewModel</code> 把它绑到落库的那一行，聊天里这一行只画成一行安静的小字「例程 · 〈名称〉 · 08:00」，而不是一条以本人口吻发出的气泡；模型收到一条只管这一轮的 <code>SessionAddenda</code>，说明情况，于是它直接从结果说起，不感谢谁的提问。到 1.0.4 为止，提示词就像本人打的字一样立在聊天里</td></tr><tr><td><code>feed/</code></td><td>动态：<code>FeedFlow</code> 维护每日定时任务和它写作所在的会话，这个会话是智能体的工作间，不进抽屉、聊天列表和主聊天的回退（<code>FeedFlow.hidden</code>，由 <code>ChatRepository.observeSessions()</code>、<code>MainChat</code> 和「移到会话」面板读取）；<code>FeedStore</code> 存帖子，最新的一天在前，一天之内最新的一批在前、每批保持模型给出的顺序（同一批共享 <code>created</code> 时间；<code>FeedStore.DAY_ORDER</code>，有单元测试）。智能体在 <code>/var/minis/feed/YYYY-MM-DD/NN.md</code> 读帖子，你点过赞的带 <code>liked: true</code>：这是一份只读副本（<code>FeedSandboxScope</code>，每条 shell 命令前和每次点赞后刷新），不是 App 自己的目录，因为 PRoot 不能把文件夹只读地绑进去，而点赞是本人的，不该由智能体改；没有 <code>liked</code> 的帖子只是还没反应，提示词里说明了这不是不喜欢。任务在 App 退到后台时写出了帖子，就发一条点出帖子标题的通知，点开进动态页（<code>minis://feed</code>），取代 1.0.4 之前那条带着模型原文、点开进会话的通用「任务完成」通知</td></tr><tr><td><code>chat/TurnReply</code></td><td>判断刚结束的这一轮到底产出了哪条助手消息：只有排在最后一条用户消息之后、且没有挂着错误的最后一条助手消息才算。动态、目标和首次对话都通过它读回复，所以模型调用在产出回复前就失败的一轮，交给它们的是空，而不是上一轮的回复（#637）</td></tr><tr><td><code>net/ModelBlip</code></td><td>沙箱里 <code>model_use</code> 调用外面的重试：网络错误、瞬时错误或 5xx 隔一秒、两秒再试，和聊天、iOS 的桥一致；其他错误直接抛出。网关自己上游没有应答的 <code>HTTP 0</code> 也按瞬时错误处理（#640）</td></tr><tr><td><code>hands/</code></td><td>作为手的无障碍服务、舞台和胶囊、屏幕读取器；<code>Hands.screenModel</code> 选屏幕模型（已选的 → 对话服务商自己的默认，当它能看图 → Cloud 给 <code>gui</code> 推荐的模型 → 自有 key 的回退模型 → 一个能看图的聊天模型 → Vision Group）</td></tr><tr><td><code>ui/coding/</code></td><td>你电脑上的编程助手</td></tr><tr><td><code>backup/</code></td><td>nanoMuse 在上游备份（<em>设置 → 备份与恢复</em>，<code>minis://settings/backup</code>）之上加的东西：「对话」下面的「对话里的文件」（默认开）可以关掉，对话就只带消息，每个会话的文件在包里只列为墓碑，其他类别不变，1.5 GB 的包因此只剩几 MB，拒收大文件的服务器也收得下（<a href="https://github.com/nano-muse/nanoMuse/issues/561" target="_blank" rel="noreferrer">#561</a>）；目的地返回 <code>413</code> 时说明是服务器的上传上限（<code>BackupHints</code>）；沙箱里的 <code>nanomuse-backup run</code> 用页面上保存的选项和所有已启用的目的地做一次备份，记入页面的历史（<code>BackupRun</code>；<code>status</code>、<code>history</code>、<code>choices</code> 读它），定时任务因此能让手机定期备份。加密开着时它会拒绝，因为口令在页面上输入、从不进入命令行；没有启用的目的地时也拒绝（<a href="https://github.com/nano-muse/nanoMuse/issues/560" target="_blank" rel="noreferrer">#560</a>）</td></tr><tr><td><code>connectors/</code>、<code>ui/connectors/</code></td><td>连接器目录（<code>ConnectorsCatalogue</code> 读取资源文件）、MCP 授权发现与注册（<code>McpAuthDiscovery</code>）、连接和令牌刷新（<code>Connectors</code>）、这台手机连接了什么并发布到 profile、其他设备连接了什么（<code>SharedConnectors</code>）、「设置 → 连接器」页面</td></tr><tr><td><code>ui/cloud/</code></td><td>登录、账号屏、设备部分</td></tr><tr><td><code>res/values*/nm_strings.xml</code></td><td>nanoMuse 的全部字符串，App 支持的十七种语言各一份（英语、简体中文、繁體中文、德语、西班牙语、菲律宾语、法语、印尼语、日语、韩语、马来语、波兰语、巴西葡萄牙语、罗马尼亚语、俄语、泰语、土耳其语）；每个文件的键相同，只有英语文件里标了 <code>translatable=&quot;false&quot;</code> 的两条（中继地址示例和产品名 <code>nanoMuse Cloud</code>）例外，缺的回落到英语</td></tr></tbody></table>`,50)])])}const k=o(a,[["render",n]]);export{u as __pageData,k as default};
